arguments.query:
select json_build_object(
 'cron_command',(select json_build_object(
  'qualified_simple_purge',regexp_replace(lower(command),'[[:space:]]','','g') in ('selectpublic.vs_purge_expired();','selectpublic.vs_purge_expired()'),
  'unqualified_simple_purge',regexp_replace(lower(command),'[[:space:]]','','g') in ('selectvs_purge_expired();','selectvs_purge_expired()'),
  'command_length',length(command)
 ) from cron.job where jobname='vs-purge-expired' and jobid=2),
 'data_api_db_schema_settings',(select json_agg(json_build_object('role',r.rolname,'setting',v))
  from pg_catalog.pg_db_role_setting s join pg_catalog.pg_roles r on r.oid=s.setrole,
  lateral unnest(s.setconfig) v where r.rolname in ('authenticator','postgres') and v like 'pgrst.db_schemas=%'),
 'connection_data_api_schema_setting',current_setting('pgrst.db_schemas',true)
) as settings;
